using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("build.binlog");
var errors = build.FindChildrenRecursive<Error>();
var warnings = build.FindChildrenRecursive<Warning>();

Console.WriteLine("=== BUILD ERRORS ===");
Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine();

// Group errors by project
var errorsByProject = new Dictionary<string, List<Error>>();
foreach (var e in errors)
{
    var project = e.GetNearestParent<Project>()?.Name ?? "(unknown)";
    if (!errorsByProject.ContainsKey(project))
        errorsByProject[project] = new List<Error>();
    errorsByProject[project].Add(e);
}

foreach (var kvp in errorsByProject.OrderBy(x => x.Key))
{
    Console.WriteLine($"--- Project: {kvp.Key} ---");
    foreach (var e in kvp.Value)
    {
        Console.WriteLine($"  [{e.Code}] {e.File}({e.LineNumber},{e.ColumnNumber}): {e.Text}");
    }
    Console.WriteLine();
}

Console.WriteLine("=== WARNINGS (potentially relevant) ===");
var relevantWarnings = warnings.Where(w => 
    w.Code != null && (w.Code.StartsWith("NU") || w.Code.StartsWith("MSB") || w.Code == "CS8632"))
    .Take(20);
foreach (var w in relevantWarnings)
{
    var project = w.GetNearestParent<Project>()?.Name ?? "(unknown)";
    Console.WriteLine($"  [{w.Code}] {project}: {w.Text}");
}

// Check for failed project references
Console.WriteLine();
Console.WriteLine("=== PROJECT BUILD ORDER & RESULTS ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    if (p.FindChildrenRecursive<Error>().Any())
        Console.WriteLine($"  FAILED: {p.Name} ({p.ProjectFile})");
}
