using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("build.binlog");

// Get all projects and their results
var projects = build.FindChildrenRecursive<Project>();
Console.WriteLine("=== ALL PROJECTS IN BUILD ===");
foreach (var p in projects)
{
    var errs = p.FindChildrenRecursive<Error>();
    Console.WriteLine($"  {(errs.Any() ? "FAIL" : "OK  ")}: {p.Name} -> {p.ProjectFile}");
}

// Look for package references in the failed project
Console.WriteLine();
Console.WriteLine("=== MESSAGES FROM FAILED PROJECT (NuGet/PackageReference related) ===");
var failedProject = projects.FirstOrDefault(p => p.Name == "Services.csproj");
if (failedProject != null)
{
    var messages = failedProject.FindChildrenRecursive<Message>();
    foreach (var m in messages.Where(m => 
        m.Text != null && (m.Text.Contains("Newtonsoft") || m.Text.Contains("PackageReference") || m.Text.Contains("NuGet") || m.Text.Contains("package") || m.Text.Contains("restore"))))
    {
        Console.WriteLine($"  {m.Text.Substring(0, Math.Min(200, m.Text.Length))}");
    }

    // Also check all targets for restore info
    var allMessages = failedProject.FindChildrenRecursive<Message>();
    Console.WriteLine($"\n  Total messages in project: {allMessages.Count}");
}

// Check if there's a project.assets.json or restore target output
Console.WriteLine();
Console.WriteLine("=== NUGET RESTORE DIAGNOSTICS ===");
var allMsgs = build.FindChildrenRecursive<Message>();
foreach (var m in allMsgs.Where(m => m.Text != null && m.Text.Contains("Newtonsoft")))
{
    Console.WriteLine($"  {m.Text.Substring(0, Math.Min(300, m.Text.Length))}");
}

// Check project file content if embedded
Console.WriteLine();
Console.WriteLine("=== ITEMS (PackageReference) ===");
if (failedProject != null)
{
    var items = failedProject.FindChildrenRecursive<Item>();
    foreach (var item in items.Where(i => i.Name == "PackageReference" || (i.Text != null && i.Text.Contains("Newtonsoft"))))
    {
        Console.WriteLine($"  Item: {item.Name} = {item.Text}");
    }

    // Check all AddItem/RemoveItem
    var addItems = failedProject.FindChildrenRecursive<AddItem>();
    foreach (var ai in addItems.Where(a => a.Name == "PackageReference"))
    {
        Console.WriteLine($"  AddItem: {ai.Name}");
        foreach (var child in ai.Children)
            Console.WriteLine($"    -> {child}");
    }
}

// Print the source lines that cause errors for context
Console.WriteLine();
Console.WriteLine("=== ERROR DETAILS ===");
var errors = build.FindChildrenRecursive<Error>();
foreach (var e in errors)
{
    Console.WriteLine($"  File: {e.File}");
    Console.WriteLine($"  Line: {e.LineNumber}, Col: {e.ColumnNumber}");
    Console.WriteLine($"  Code: {e.Code}");
    Console.WriteLine($"  Text: {e.Text}");
    Console.WriteLine();
}
