using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("build.binlog");

// Get the failed Services.csproj build evaluation to find its PackageReferences
var projects = build.FindChildrenRecursive<Project>();

// Find embedded file contents
Console.WriteLine("=== LOOKING FOR EMBEDDED SOURCE FILES ===");
var sourceFiles = build.FindChildrenRecursive<SourceFile>();
Console.WriteLine($"SourceFile nodes: {sourceFiles.Count}");

// Check for file embeds
var sourceFilePaths = build.FindChildrenRecursive<SourceFileLine>();
Console.WriteLine($"SourceFileLine nodes: {sourceFilePaths.Count}");

// Try to find the project file content in items
Console.WriteLine();
Console.WriteLine("=== ALL NAMED NODES IN FAILED PROJECT ===");
var failedProjects = projects.Where(p => p.FindChildrenRecursive<Error>().Any() && p.Name == "Services.csproj");
foreach (var fp in failedProjects)
{
    Console.WriteLine($"\nProject: {fp.Name} (ID: {fp.Id})");
    // Walk all direct children
    void Walk(BaseNode node, int depth) {
        if (depth > 4) return;
        var indent = new string(' ', depth * 2);
        Console.WriteLine($"{indent}{node.GetType().Name}: {node}");
        if (node is TreeNode tn) {
            foreach (var child in tn.Children.Take(50))
                Walk((BaseNode)child, depth + 1);
        }
    }
    Walk(fp, 0);
}

// Also check for items named "Reference" or "PackageReference" globally
Console.WriteLine();
Console.WriteLine("=== PACKAGE REFERENCES IN EVALUATION ===");
var namedNodes = build.FindChildrenRecursive<NamedNode>();
foreach (var nn in namedNodes.Where(n => n.Name == "PackageReference").Take(20))
{
    Console.WriteLine($"  {nn.GetType().Name}: {nn.Name} -> {nn}");
    if (nn is TreeNode tn2)
        foreach (var c in tn2.Children.Take(10))
            Console.WriteLine($"    child: {c}");
}
